import { authFetch } from '../../api/authApi';

// Post-story recall quiz — generated by the same AI service used for
// Calendar event card text, following the same try-AI-then-fallback
// pattern. When the AI call fails, `quiz` comes back null and no attempt
// is ever created (see backend/src/services/family/storyQuizService.js) —
// the UI should just render nothing in that case.

export interface StoryQuizQuestion {
  questionText: string;
  options: string[];
  selectedOptionIndex: number | null;
  isCorrect: boolean | null;
}

export interface StoryQuizAttempt {
  attemptId: string;
  memoryId: string;
  sessionId: string;
  status: 'in_progress' | 'completed';
  score: number | null;
  totalQuestions: number;
  questions: StoryQuizQuestion[];
}

export const generateStoryQuiz = async (
  memoryId: string,
  sessionId: string
): Promise<StoryQuizAttempt | null> => {
  try {
    const data = await authFetch('/family/story-quiz/generate', {
      method: 'POST',
      body: JSON.stringify({ memoryId, sessionId }),
    });
    return data?.success ? data.quiz : null;
  } catch (error: any) {
    console.error('Generate story quiz error:', error.message);
    return null;
  }
};

export interface AnswerQuestionResult {
  success: boolean;
  questionIndex: number;
  isCorrect: boolean;
  correctOptionIndex: number;
  sourceSnippet: string;
  quizComplete: boolean;
  score: number | null;
  totalQuestions: number;
}

export const answerStoryQuizQuestion = async (
  attemptId: string,
  questionIndex: number,
  selectedOptionIndex: number
): Promise<AnswerQuestionResult | null> => {
  try {
    const data = await authFetch(`/family/story-quiz/${attemptId}/answer`, {
      method: 'POST',
      body: JSON.stringify({ questionIndex, selectedOptionIndex }),
    });
    return data?.success ? data : null;
  } catch (error: any) {
    console.error('Answer story quiz question error:', error.message);
    return null;
  }
};

// family-only — marks a completed quiz as seen, same "seen on view" trigger
// pattern as markReactionSeen for Calendar reactions
export const markQuizSeenByFamily = async (attemptId: string): Promise<boolean> => {
  try {
    const data = await authFetch(`/family/story-quiz/${attemptId}/seen`, { method: 'PATCH' });
    return !!data?.success;
  } catch (error: any) {
    console.error('Mark quiz seen error:', error.message);
    return false;
  }
};
